const settings = $('Shortlist settings').first().json;
const preferredBrand = String(settings.preferredBrand ?? '').trim().toUpperCase();
const minReachM = Number(settings.minReachM ?? 0);
const maxReachM = Number(settings.maxReachM ?? 0);
if (![minReachM, maxReachM].every(Number.isFinite) || minReachM < 0 || maxReachM < 0 ||
    (minReachM && maxReachM && minReachM > maxReachM)) {
  throw Error('Set valid minReachM and maxReachM values in Shortlist settings');
}

const safe = (value) => {
  const s = String(value ?? '').trim();
  return /^[=+@\-\t\r]/.test(s) ? "'" + s : s;
};
const products = $input.all().flatMap((item) =>
  Array.isArray(item.json) ? item.json : [item.json]
);
const output = [];
for (const product of products) {
  if (!product || !Number.isInteger(Number(product.id))) continue;
  const name = String(product.name ?? '').trim();
  const link = String(product.permalink ?? '').trim();
  if (!name || !/^https:\/\/[^\s]+$/i.test(link)) continue;
  const categoryNames = Array.isArray(product.categories)
    ? product.categories.map((c) => String(c.name ?? '')).join(' ')
    : '';
  if (!/concrete pump truck/i.test(name) && !/Truck-Mounted Concrete Pump/i.test(categoryNames)) continue;
  const brandMatch = /\b(SANY|Zoomlion|XCMG)\b/i.exec(name);
  const brand = brandMatch ? brandMatch[1].toUpperCase() : 'UNSPECIFIED';
  if (preferredBrand && brand !== preferredBrand.toUpperCase()) continue;
  const reachMatch = /\b(\d{2}(?:\.\d+)?)\s*(?:m|meters?)\b/i.exec(name);
  const reachM = reachMatch ? Number(reachMatch[1]) : null;
  if ((minReachM || maxReachM) && reachM === null) continue;
  if (minReachM && reachM < minReachM) continue;
  if (maxReachM && reachM > maxReachM) continue;
  output.push({ json: {
    catalogId: String(product.id),
    brand: safe(brand),
    boomReachM: reachM ?? '',
    listingTitle: safe(name),
    productUrl: safe(link),
    reviewNote: 'Catalog reference only; confirm current availability, condition and quotation with the seller.'
  } });
}
if (!output.length) {
  return [{ json: {
    catalogId: '', brand: '', boomReachM: '', listingTitle: 'No matching catalog references',
    productUrl: '', reviewNote: 'Change the brand or reach filters and run again.'
  } }];
}
return output;
